        'left:50%',
        'transform:translate(-50%,-50%)',
        'font-family:\'Arial Black\',Arial,sans-serif',
        'font-size:36px',
        'font-weight:900',
        'color:#fff',
        'letter-spacing:6px',
        'text-transform:uppercase',
        'text-shadow:0 0 20px rgba(255,80,0,0.9),0 2px 6px rgba(0,0,0,0.9)',
        'pointer-events:none',
        'z-index:2001',
        'opacity:0',
