        'position:fixed',
        'top:0', 'left:0', 'right:0', 'bottom:0',
        'background:radial-gradient(ellipse at center,transparent 55%,rgba(0,0,0,0.7) 100%)',
        'pointer-events:none',
        'z-index:1999',
        'opacity:0',
