        var tid = setTimeout(function () {
          var freqLow  = 300 + Math.random() * 400;
          var freqHigh = freqLow + 500 + Math.random() * 2000;
          _playNoiseBurst(0.35, freqLow, freqHigh, 0.15 + Math.random() * 0.2);
        }, t);
        _soundIntervals.push(tid);
