      smokeEl.id = 'smoke-screen-effect';
      smokeEl.style.cssText = 'position:fixed;top:0;left:0;width:100%;height:100%;pointer-events:none;z-index:1200;background:rgba(150,150,150,0);transition:background 0.5s';
