    _rappelling      = true;
    _brakeOn         = false;
    _fastRope        = true;
    _rappelComplete  = false;
    _anchorX         = pos.x;
    _anchorY         = pos.y;
    _anchorZ         = pos.z;
    _targetY         = 0;
    _startY          = pos.y;
    _descentDuration = pos.y / FAST_ROPE_SPEED;
    _descentElapsed  = 0;
    _swingOffset     = 0;
    _swingVel        = 0;

