    _showProgressBar(false);
    _hideWireOverlay();

    var pos = _bombGroup ? _bombGroup.position.clone() : new THREE.Vector3();

    // Remove bomb mesh
    if (_bombGroup && _scene) {
      _scene.remove(_bombGroup);
      _bombGroup = null;
    }

    // Sound
    _playExplosionSound();

    // Camera shake
    window._cameraShake = { intensity: 2.0, duration: 1.8 };

    // Fire particles
    _spawnFireParticles(pos);

