        'top:40%',
        'left:50%',
        'transform:translateX(-50%) translateY(0px)',
        'font-family:monospace',
        'font-size:22px',
        'font-weight:bold',
        'color:' + color,
        'text-shadow:0 0 12px ' + color,
        'z-index:9000',
        'pointer-events:none',
        'white-space:nowrap',
        'transition:transform 1.5s ease-out, opacity 1.5s ease-out',
        'opacity:1'
