      var hasVehicle = _fireworksTypes.vehicle && (now - _fireworksTypes.vehicle) < _fireworksWindowMs;
      var hasAmmo    = _fireworksTypes.ammo    && (now - _fireworksTypes.ammo)    < _fireworksWindowMs;
