  function reset() {
    if (_comboTimeoutId !== null) {
      clearTimeout(_comboTimeoutId);
      _comboTimeoutId = null;
    }
    _comboCount = 0;
    _totalScore = 0;
    _bestCombo = 0;
    _fireworksTypes = {};
    _fireworksAwarded = false;
    window._bestDestrCombo = 0;
  }

