        var py = src.y + (dst.y - src.y) * t + (Math.random() - 0.5) * 0.2;
        var pz = src.z + (dst.z - src.z) * t + (Math.random() - 0.5) * 0.25 * (1 - Math.abs(t - 0.5) * 2);
