    if (!ctx) return;
    /* Paper rustle: shaped noise burst */
    var sr  = ctx.sampleRate;
    var len = Math.floor(sr * 0.25);
    var buf = ctx.createBuffer(1, len, sr);
    var d   = buf.getChannelData(0);
    for (var i = 0; i < len; i++) {
      d[i] = (Math.random() * 2 - 1) * Math.pow(1 - i / len, 2) * 0.3;
    }
