    src.buffer = buf;
    var bp  = ctx.createBiquadFilter();
    bp.type = 'bandpass';
    bp.frequency.value = 800;
    bp.Q.value = 1.2;
    src.connect(bp);
    bp.connect(ctx.destination);
    src.start();

