      var baseY = topY * (1 - t);
      var baseZ = dz * t;

      if (i > 0 && i < segCount) {
        // random jagged offset ±1 unit in X and Z
        baseX += _randRange(-1, 1);
        baseZ += _randRange(-1, 1);
      }

