        // Rotating ring above
        var ringGeo = new THREE.TorusGeometry(0.45, 0.06, 8, 24);
        var ringMat = new THREE.MeshStandardMaterial({
          color: COLOR_UNUSED,
          emissive: COLOR_UNUSED,
          emissiveIntensity: 0.6
        });
