      px: playerPos.x,
      py: playerPos.y,
      pz: playerPos.z,
      hp:    typeof _player.hp    !== 'undefined' ? _player.hp    : 100,
      ammo:  typeof _player.ammo  !== 'undefined' ? _player.ammo  : 30,
