    canvas.width  = 256;
    canvas.height = 64;
    var ctx = canvas.getContext('2d');
    ctx.fillStyle = '#3b4a1e';
    ctx.fillRect(0, 0, 256, 64);
    ctx.strokeStyle = '#c8b850';
    ctx.lineWidth = 2;
    ctx.strokeRect(3, 3, 250, 58);
    ctx.fillStyle = '#f0d060';
