    var bodyGeo = new THREE.CylinderGeometry(0.05, 0.05, 0.3, 8);
    var bodyMat = new THREE.MeshLambertMaterial({
      color: 0xFF1111,
      emissive: 0x550000,
      emissiveIntensity: 0.4
    });
