    _addScore(SCORE_PER_CRATE);

    _toast('📦 CRATE SECURED! +' + SCORE_PER_CRATE + '  Deliver to extraction!', 3000, '#ffdd44');

    try { if (window.AudioSystem && AudioSystem.playPickup) AudioSystem.playPickup(); } catch (e) {}

