      'position:fixed',
      'top:28%',
      'left:50%',
      'transform:translateX(-50%)',
      'color:#ffe600',
      'font:bold 18px/1.4 monospace',
      'text-shadow:0 0 8px #ff8800',
      'pointer-events:none',
