  /* ── Pending (pad A placed, waiting for pad B) ────────────── */
  var _pending = null;   // pad object or null

  /* ── Animation clock ─────────────────────────────────────── */
  var _clock = 0;

  /* ── Key state ────────────────────────────────────────────── */
  var _tKeyDown = false;

  /* ── AudioContext ──────────────────────────────────────────── */
  var _audioCtx = null;

  /* ── HUD badge element ────────────────────────────────────── */
  var _hudBadge = null;

