        lid:          crate.lid,
        paraGroup:    parachute.group,
        paraCone:     parachute.cone,
        paraConeMat:  parachute.coneMat,
        targetY:      targetY,
        landed:       false,
        opened:       false,
        collected:    false,
        time:         0,
        reward:       _pickReward(),
