  var BUBBLE_HP_MAX   = 300;
  var BUBBLE_RADIUS   = 2.5;
  var ALLY_SCAN_DIST  = 12;
  var DAMAGE_FACTOR   = 0.30;   /* 30 % damage passes through bubble */
