    _energy       = MAX_ENERGY;
    _depleted     = false;
    _recharging   = false;
    _rechargeTimer = 0;
    _time         = 0;

    window._stealthActive = false;
    window._stealthEnergy = MAX_ENERGY;
    window._muteFootsteps = false;

    _clearCanvasFilter();
    _stopHum();
    _restoreEnemyDetection();
    _removePickup();

