      var gain   = ctx.createGain();
      src.buffer = buf;
      var filt   = ctx.createBiquadFilter();
      filt.type  = 'lowpass';
      filt.frequency.value = 120;
      src.connect(filt);
      filt.connect(gain);
      gain.connect(ctx.destination);
