        'position:fixed',
        'bottom:30px',
        'left:50%',
        'transform:translateX(-50%)',
        'z-index:8500',
        'font-family:monospace',
        'font-size:12px',
        'color:#ff4444',
        'text-align:center',
        'pointer-events:none',
