    var sGeo = new THREE.SphereGeometry(0.9 + Math.random() * 0.4, 6, 4);
    var sMat = new THREE.MeshBasicMaterial({ color: 0x444444, transparent: true, opacity: 0.55 });
    var sMesh = new THREE.Mesh(sGeo, sMat);
