        if (typeof Enemies !== 'undefined' && Enemies.damage) {
          Enemies.damage(e, BLAST_RADIUS_DMG);
        } else if (e.hp !== undefined) {
          e.hp = Math.max(0, e.hp - BLAST_RADIUS_DMG);
        }
